internal fun app.resound.data.MemoryItemEntity.snapshot() = app.resound.digest.core.MemoryItemData(id = id, eventId = eventId, category = category, kind = kind, content = content, dueText = dueText, dueAt = dueAt, who = who, lineId = lineId, status = status, createdAt = createdAt, doneAt = doneAt, statusChangedAt = statusChangedAt, sortOrder = sortOrder, mergedInto = mergedInto, noMerge = noMerge, deleted = deleted, editedAt = editedAt, doneHintLineId = doneHintLineId, doneHintAt = doneHintAt, dismissedDoneLinesJson = dismissedDoneLinesJson, reminderVersion = reminderVersion, origin = origin, sourceText = sourceText, strongReminder = strongReminder)
